/*
a = x ∘ w
                    b = x × w
                    c = x ⋅ w
                    where
                    x: ℤ ^ 3
                    w: ℤ ^ 3
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    Eigen::Matrix<int, 3, 1> a;
    Eigen::Matrix<int, 3, 1> b;
    int c;

    heartlib(
        const Eigen::Matrix<int, 3, 1> & x,
        const Eigen::Matrix<int, 3, 1> & w)
    {

        // a = x ∘ w
        a = (x).cwiseProduct(w);
        // b = x × w
        b = (x).cross(w);
        // c = x ⋅ w
        c = (x).dot(w);
    }
};

