function output = heartlib(x, w)
% output = heartlib(x, w)
%
%    a = x ∘ w
%                        b = x × w
%                        c = x ⋅ w
%                        where
%                        x: ℤ ^ 3
%                        w: ℤ ^ 3
    x = reshape(x,[],1);
    w = reshape(w,[],1);

    assert( numel(x) == 3 );
    assert( numel(w) == 3 );

    % a = x ∘ w

    a = x.*w;
    % b = x × w

    b = cross(x, w);
    % c = x ⋅ w

    c = dot(x,w);
    output.a = a;
    output.b = b;
    output.c = c;
end

